begin;
with j as (select * from jsonb_to_recordset($law7d0007$[{"code_id":"APK_RF","article_number":"203","version_date":"2002-07-24","article_text":"Заявление о привлечении к административной ответственности подается в арбитражный суд по адресу или месту жительства лица, в отношении которого составлен протокол об административном правонарушении. В случае, если лицо, в отношении которого составлен протокол об административном правонарушении, привлекается за административное правонарушение, совершенное вне места его нахождения или места его жительства, указанное заявление может быть подано в арбитражный суд по месту совершения административного правонарушения. (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 28.11.2018 № 451-ФЗ)","article_title":"Статья 203. Подача заявления о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a486ec659e8421069a617f23fb46ecb6af1dfc37863e94316c25a20b101409dd"},{"code_id":"APK_RF","article_number":"204","version_date":"2002-07-24","article_text":"1. Заявление о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) дата и место совершения действий, послуживших основанием для составления протокола об административном правонарушении;\n\n2) должность, фамилия и инициалы лица, составившего протокол об административном правонарушении;\n\n3) сведения о лице, в отношении которого составлен протокол об административном правонарушении;\n\n4) нормы закона, предусматривающего административную ответственность за действия, послужившие основанием для составления протокола об административном правонарушении;\n\n5) требование заявителя о привлечении к административной ответственности.\n\n2. К заявлению прилагаются протокол об административном правонарушении и прилагаемые к протоколу документы, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления лицу, в отношении которого составлен протокол об административном правонарушении.","article_title":"Статья 204. Требования к заявлению о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7802377a1009ddfab7e239273537adbe6cf9b4b191057b0bcc5ff234120a1833"},{"code_id":"APK_RF","article_number":"205","version_date":"2002-07-24","article_text":"В случае непредставления административным органом, составившим протокол, доказательств, необходимых для рассмотрения дела и принятия решения, арбитражный суд может истребовать доказательства от указанного органа по своей инициативе.","article_title":"Статья 205. Судебное разбирательство по делам о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f8e044d3d4b236973a8fbe4cfd6f5b0d6e68f38c43390102b205759fe206a6c"},{"code_id":"APK_RF","article_number":"206","version_date":"2002-07-24","article_text":"1. Решение по делу о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения заявления о привлечении к административной ответственности арбитражный суд принимает решение о привлечении к административной ответственности или об отказе в удовлетворении требования административного органа о привлечении к административной ответственности.\n\n3. В резолютивной части решения о привлечении к административной ответственности должны содержаться:\n\n1) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) нормы закона, на основании которых данное лицо привлекается к административной ответственности;\n\n3) вид административного наказания и санкции, возложенные на лицо, привлеченное к административной ответственности.\n\n4. Решение по делу о привлечении к административной ответственности вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n5. Копия решения арбитражного суда по делу о привлечении к административной ответственности направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 206. Решение арбитражного суда по делу о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53740a1e54302582ec750aa8f29176ce58aaccf2905a9a739951f87b71d6daf3"},{"code_id":"APK_RF","article_number":"207","version_date":"2002-07-24","article_text":"1. Дела об оспаривании решений государственных органов, иных органов, должностных лиц, уполномоченных в соответствии с федеральным зак\n\nоном рассматривать дела об административных правонарушениях (далее в параграфе 2 главы 25, пункте 4 части 1 статьи 227 настоящего Кодекса - административные органы), о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе и федеральном законе об административных правонарушениях. (В редакции Федерального закона от 25.06.2012 № 86-ФЗ)","article_title":"Статья 207. Порядок рассмотрения дел об оспаривании решений административных органов о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b09e913a4ba26ffbfab72dc6d6c860a94a9a9da503114fa830e3d83e0dc1a8c5"},{"code_id":"APK_RF","article_number":"208","version_date":"2002-07-24","article_text":"В случае пропуска указанного срока он может быть восстановлен судом по ходатайству заявителя.","article_title":"Статья 208. Подача заявления об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd71292b482af83ef3212cd490f600b286154c53b5f248fcd4aab1a0db238c4"},{"code_id":"APK_RF","article_number":"209","version_date":"2002-07-24","article_text":"1. Заявление об оспаривании решения административного органа о привлечении к административной ответственности должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование административного органа, принявшего оспариваемое решение;\n\n2) название, номер, дата принятия оспариваемого решения и иные сведения о нем;\n\n3) права и законные интересы заявителя, которые нарушены, по его мнению, оспариваемым решением;\n\n4) требование заявителя и основания, по которым он оспаривает решение административного органа.\n\n2. К заявлению об оспаривании решения административного органа прилагаются текст оспариваемого решения, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления об оспаривании решения в административный орган, его принявший.","article_title":"Статья 209. Требования к заявлению об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"166cd53dda0bffea7a239f1e15d1756db3fc9641c34d4d9c522aee15735772cd"},{"code_id":"APK_RF","article_number":"21","version_date":"2002-07-24","article_text":"1. Судья не может участвовать в рассмотрении дела и подлежит отводу, если он:\n\n1) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи и его повторное участие в рассмотрении дела в соответствии с требованиями настоящего Кодекса является недопустимым;\n\n2) при предыдущем рассмотрении данного дела участвовал в нем в качестве прокурора, помощника судьи, секретаря судебного заседания, представителя, эксперта, специалиста, переводчика или свидетеля; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n3) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи иностранного суда, третейского суда или арбитража;\n\n31) являлся судебны\n\nм примирителем по данному делу; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) является родственником лица, участвующего в деле, или его представителя;\n\n5) лично, прямо или косвенно заинтересован в исходе дела либо имеются иные обстоятельства, которые могут вызвать сомнение в его беспристрастности;\n\n6) находится или ранее находился в служебной или иной зависимости от лица, участвующего в деле, или его представителя;\n\n7) делал публичные заявления или давал оценку по существу рассматриваемого дела.\n\n2. В состав арбитражного суда, рассматривающего дело, не могут входить лица, являющиеся родственниками.","article_title":"Статья 21. Отвод судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1437f3e0ba501003e8e23dafec0bd0b00500b83d35fe186b3a4754bfa5b1c7b2"},{"code_id":"APK_RF","article_number":"211","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании решения административного органа о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что оспариваемое решение или порядок его принятия не соответствует закону, либо отсутствуют основания для привлечения к административной ответственности или применения конкретной меры ответственности, либо оспариваемое решение принято органом или должностным лицом с превышением их полномочий, суд принимает решение о признании незаконным и об отмене оспариваемого решения полностью или в части либо об изменении решения.\n\n3. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что решение административного органа о привлечении к административной ответственности является законным и обоснованным, суд принимает решение об отказе в удовлетворении требования заявителя.\n\n4. В резолютивной части решения по делу об оспаривании решения административного органа должны содержаться:\n\n1) название, номер, дата и место принятия, другие необходимые сведения об оспариваемом решении;\n\n2) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) указание на признание решения незаконным и его отмену полностью или в части, либо на отказ в удовлетворении требования заявителя полностью или в части, либо на меру ответственности, если она изменена судом.\n\n5. Решение арбитражного суда вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам об оспаривании решений административных органов о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6. Копия решения направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 211. Решение арбитражного суда по делу об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"712f5c654f8f005fc466da7036b14717f5717e68b61236d10cc38f583776a40a"},{"code_id":"APK_RF","article_number":"213","version_date":"2002-07-24","article_text":"1. Государственные органы, органы местного самоуправления, иные органы, наделенные в соответствии с федеральным законом контрольными функциями (далее - контрольные органы), вправе обратиться в арбитражный суд с заявлением о взыскании с лиц, осуществляющих предпринимательскую и иную экономическую деятельность, установленных законом обязательных платежей и санкций, если федеральным законом не предусмотрен иной порядок их взыскания.\n\n2. Заявление о взыскании подается в арбитражный суд, если не исполнено требование заявителя об уплате взыскиваемой суммы в добровольном порядке или пропущен указанный в таком требовании срок уплаты.","article_title":"Статья 213. Право на обращение в арбитражный суд с заявлением о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54b895e11263d6a9d7a2fe50c5d840c8f0cb75d05e9b0cab04039fbd3a1863f8"},{"code_id":"APK_RF","article_number":"214","version_date":"2002-07-24","article_text":"1. Заявление о взыскании обязательных платежей и санкций должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование платежа, подлежащего взысканию, размер и расчет его суммы;\n\n2) нормы федерального закона и иного нормативного правового акта, предусматривающие уплату платежа;\n\n3) сведения о направлении требования об уплате платежа в добровольном порядке.\n\n2. К заявлению о взыскании обязательных платежей и санкций прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также документ, подтверждающий направление заявителем требования об уплате взыскиваемого платежа в добровольном порядке.","article_title":"Статья 214. Требования к заявлению о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e70557b982a9a9a1011819956338b9d8ed36788da1e0504b1934ed92b9096fd8"},{"code_id":"APK_RF","article_number":"215","version_date":"2002-07-24","article_text":"Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 215. Судебное разбирательство по делам о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9d23f9828e18c6381a8926a4ea5cce055b2ec434d51878f7d30b66c9c7869c4"},{"code_id":"APK_RF","article_number":"216","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций принимается по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. При удовлетворении требования о взыскании обязательных платежей и санкций в резолютивной части решения должны быть указаны:\n\n1) наименование лица, обязанного уплатить сумму задолженности, его адрес или место жительства, сведения о его государственной регистрации; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) общий размер подлежащей взысканию денежной суммы с определением отдельно основной задолженности и санкций.\n\nРАЗДЕЛ IV. ОСОБЕННОСТИ ПРОИЗВОДСТВА В АРБИТРАЖНОМ СУДЕ ПО ОТДЕЛЬНЫМ КАТЕГОРИЯМ ДЕЛ","article_title":"Статья 216. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93dffa32380988133389c464c7d51e18c6a38133e70bafd71761f11b0bebf139"},{"code_id":"APK_RF","article_number":"217","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются арбитражным судом по общим правилам искового производства, установленным настоящим Кодексом, с особенностями, предусмотренными в настоящей главе.\n\n2. Производство по делам об установлении фактов, имеющих юридическое значение, возбуждается в арбитражном суде на основании заявлений об установлении фактов, имеющих юридическое значение.\n\n3. В случае, если при рассмотрении дела об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве, арбитражный суд оставляет заявление об установлении фактов, имеющих юридическое значение, без рассмотрения, о чем выносит определение. В определении заявителю и другим заинтересованным лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 217. Порядок рассмотрения дел об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6bbcd99a99ed1fc61ea29d118e26998108205f8a82b58ff8e1202f8c7569b1a"},{"code_id":"APK_RF","article_number":"218","version_date":"2002-07-24","article_text":"1. Арбитражный суд устанавливает факты, имеющие юридическое значение для возникновения, изменения или прекращения прав юридических лиц и индивидуальных предпринимателей в сфере предпринимательской и иной экономической деятельности.\n\n2. Арбитражный суд рассматривает дела об установлении:\n\n1) факта владения и пользования юридическим лицом или индивидуальным предпринимателем недвижимым имуществом как своим собственным;\n\n2) факта государственной регистрации юридического лица или индивидуального предпринимателя в определенное время и в определенном месте;\n\n3) факта принадлежности правоустанавливающего документа, действующего в сфере предпринимательской и иной экономической деятельности, юридическому лицу или индивидуальному предпринимателю, если наименование юридического лица, имя, отчество или фамилия индивидуального предпринимателя, указанные в документе, не совпадают с наименованием юридического лица по его учредительному документу, именем, отчеством или фамилией индивидуального предпринимателя по его паспорту или свидетельству о рождении;\n\n4) других фактов, порождающих юридические последствия в сфере предпринимательской и иной экономической деятельности.","article_title":"Статья 218. Дела об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146df9a6093d236985e4e16fe13b480ea4c748dd8696b5be85a3c886c9024200"},{"code_id":"APK_RF","article_number":"219","version_date":"2002-07-24","article_text":"1. Юридическое лицо или индивидуальный предприниматель вправе обратиться в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение, только если у заявителя отсутствует возможность получить или восстановить надлежащие документы, удостоверяющие эти факты, и если федеральным законом или иным нормативным правовым актом не предусмотрен иной внесудебный порядок установления соответствующих фактов.","article_title":"Статья 219. Право на обращение в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5853c78138c11a470c1ec5d53d04e3e780e1e479918ca49701a8b36942d17560"},{"code_id":"APK_RF","article_number":"22","version_date":"2002-07-24","article_text":"1. Судья, принимавший участие в рассмотрении дела в арбитражном суде первой инстанции, не может участвовать в рассмотрении этого дела в судах апелляционной и кассационной инстанций, а также в порядке надзора.\n\n2. Судья, принимавший участие в рассмотрении дела в арбитражном суде апелляционной инстанции, не может участвовать в рассмотрении этого дела в судах первой и кассационной инстанций, а также в порядке надзора.\n\n3. Судья, принимавший участие в рассмотрении дела в арбитражном суде кассационной инстанции, не может участвовать в рассмотрении этого дела в судах первой и апелляционной инстанций, а также в порядке надзора.\n\n4. Судья, принимавший участие в рассмотрении дела в порядке надзора, не может участвовать в рассмотрении этого дела в судах первой, апелляционной и кассационной инстанций.","article_title":"Статья 22. Недопустимость повторного участия судьи в рассмотрении дела","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8bdae3e6a59a30e16471209d4979aa45bb31a2579e96eb9d79c59b8c9dd77413"},{"code_id":"APK_RF","article_number":"220","version_date":"2002-07-24","article_text":"1. Заявление об установлении фактов, имеющих юридическое значение, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) факт, об установлении которого ходатайствует заявитель;\n\n2) нормы закона, предусматривающего, что данный факт порождает юридические последствия в сфере предпринимательской и иной экономической деятельности;\n\n3) обоснование необходимости установления данного факта;\n\n4) доказательства, подтверждающие невозможность получения заявителем надлежащих доказательств или восстановления утраченных документов.\n\n2. К заявлению об установлении фактов, имеющих юридическое значение, прилагаются документы, предусмотренные пунктами 2 - 5 статьи 126 настоящего Кодекса.","article_title":"Статья 220. Требования к заявлению об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98ba3590a50166d901856bfe2bb0b8581e938a9589729c8a5d82a55e478d8fe8"},{"code_id":"APK_RF","article_number":"221","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются судьей единолично в судебном заседании с участием заявителя и других заинтересованных лиц. К их рассмотрению не могут привлекаться арбитражные заседатели.\n\n2. При подготовке дела к су\n\nдебному разбирательству судья определяет круг заинтересованных по делу лиц, права которых может затронуть решение об установлении факта, имеющего юридическое значение, извещает этих лиц о производстве по делу, рассматривает вопрос о привлечении их к участию в деле, извещает о времени и месте судебного заседания.\n\n3. При рассмотрении дела об установлении факта, имеющего юридическое значение, арбитражный суд в судебном заседании проверяет, не предусмотрен ли законом или иным нормативным правовым актом иной внесудебный порядок установления данного факта, имелась ли у заявителя другая возможность получить или восстановить необходимые документы, устанавливает, порождает ли данный факт юридически значимые последствия для заявителя в связи с осуществлением им предпринимательской или иной экономической деятельности, выясняет, не затрагивает ли права других лиц установление требуемого факта, не возник ли спор о праве.\n\n4. В случае, если в ходе судебного разбирательства по делу об установлении факта, имеющего юридическое значение, выяснится, что возник спор о праве, арбитражный суд оставляет заявление об установлении факта, имеющего юридическое значение, без рассмотрения, о чем выносит определение.\n\nВ определении заявителю и другим заинтересованным по делу лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 221. Судебное разбирательство по делам об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf0da91d21bd65ba118de19af4cf1097bbad85c60e1ac7a75dd6e36c14e4033a"},{"code_id":"APK_RF","article_number":"222","version_date":"2002-07-24","article_text":"1. Решение по делу об установлении факта, имеющего юридическое значение, принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. При удовлетворении судом заявления об установлении факта, имеющего юридическое значение, в резолютивной части решения указывается на наличие факта, имеющего юридическое значение, и излагается установленный факт.\n\n3. Решение арбитражного суда об установлении факта, имеющего юридическое значение, является основанием для регистрации такого факта или оформления прав, которые возникают в связи с установленным фактом, соответствующими органами и не заменяет собой документы, выдаваемые этими органами.\n\n(Дополнение главой - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 222. Решение арбитражного суда по делу об установлении факта, имеющего юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c20000cda2cbd87e2f8bcd326936f845de37b2924df7c47c7d967829f8da42c8"},{"code_id":"APK_RF","article_number":"222.1","version_date":"2002-07-24","article_text":"1. Лицо, полагающее, что государственным органом, органом местного самоуправления, иным органом, организацией, должностным лицом нарушено его право на судопроизводство в разумный срок или право на исполнение судебного акта в разумный срок, вправе обратиться в арбитражный суд с заявлением о присуждении компенсации.\n\n2. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок может быть подано заинтересованным лицом в течение шести месяцев со дня вступления в законную силу последнего судебного акта, принятого по данному делу.\n\nЗаявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок может быть также подано до окончания производства по делу в случае, если продолжительность рассмотрения дела превышает три года и заинтересованное лицо ранее обращалось с заявлением об ускорении рассмотрения дела в порядке, установленном настоящим Кодексом.\n\n3. Заявление о присуждении компенсации за нарушение права на исполнение судебного акта в разумный срок может быть подано заинтересованным лицом в арбитражный суд до окончания производства по исполнению судебного акта, но не ранее чем через шесть месяцев со дня истечения срока, установленного федеральным законом для исполнения судебного акта, и не позднее чем через шесть месяцев со дня окончания производства по исполнению судебного акта.\n\n4. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок не может рассматриваться судьей, если он ранее принимал участие в рассмотрении дела, в связи с которым возникли основания для подачи такого заявления.","article_title":"Статья 222.1. Право на обращение в арбитражный суд с заявлением о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b1c3a01906d2dc49c1e2a6367275be1880be168aa97494178dc2b23662150f5"},{"code_id":"APK_RF","article_number":"222.2","version_date":"2002-07-24","article_text":"1. Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок подается в арбитражный суд, полномочный рассматривать такое заявление, через арбитражный суд, принявший решение.\n\n2. Арбитражный суд, принявший решение, обязан направить заявление о присуждении компенсации, указанной в части 1 настоящей статьи, вместе с делом в соответствующий суд в трехдневный срок со дня поступления такого заявления в арбитражный суд.","article_title":"Статья 222.2. Порядок подачи заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d0f54e9a69d7cac22b79eda47e9fd62dfd135c1140139bfb0bafea439bd88892"},{"code_id":"APK_RF","article_number":"222.3","version_date":"2002-07-24","article_text":"В заявлении о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование лица, подающего заявление, с указанием его процессуального положения, адреса или места жительства, наименования других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) сведения о судебном акте, принятом по делу, предмет спора, наименование арбитражного суда, рассматривавшего дело, сведения об актах и о действиях органа, организации или должностного лица, на которые возложены обязанности по исполнению судебного акта;\n\n4) общая продолжительность судопроизводства по делу, исчисляемая со дня поступления искового заявления или заявления в арбитражный суд первой инстанции до дня принятия последнего судебного акта по делу, или общая продолжительность исполнения судебного акта;\n\n5) обстоятельства, известные лицу, подающему заявление, и повлиявшие на длительность судопроизводства по делу или на длительность исполнения судебного акта;\n\n6) доводы лица, подающего заявление, с указанием оснований для присуждения компенсации и ее размера;\n\n7) последствия нарушения права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок и их значимость для заявителя;\n\n8) реквизиты банковского счета лица, подающего заявление, на который должны быть перечислены средства, подлежащие взысканию;\n\n9) перечень прилагаемых к заявлению документов.","article_title":"Статья 222.3. Требования к заявлению о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3df148aee9ba003ee808e1d6749e380fd6167d6348e418067750e3f1571a728c"}]$law7d0007$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
